import sys
from math import gcd

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            A = [int(next(iterator)) for _ in range(N)]
        except StopIteration:
            break

        adj = []
        for i in range(N):
            g = gcd(A[i], A[(i + 1) % N])
            if g == 1:
                adj.append(0)
            else:
                adj.append(1)

        if all(x == 1 for x in adj):
            results.append(" ".join(["0"] * (N - 1)))
            continue

        if all(x == 0 for x in adj):
            ans = []
            for k in range(2, N + 1):
                needed = N - k + 1
                ans.append(str(needed))
            results.append(" ".join(ans))
            continue

        adj_double = adj + adj
        n_adj = len(adj_double)

        dp = [-1] * n_adj
        for i in range(n_adj):
            if adj_double[i] == 0:
                dp[i] = 0
            else:
                dp[i] = 1

        for k in range(2, N + 1):
            best = float('inf')
            for start in range(N):
                current_len = 0
                count = 0
                for j in range(k):
                    idx = (start + j) % N
                    if adj[idx] == 0:
                        current_len += 1
                    else:
                        if current_len > 0:
                            count += 1
                        current_len = 0
                if current_len > 0:
                    count += 1

                if count < best:
                    best = count

            results.append(str(best))

        results.append(" ".join(results[-(N-1):]))
        del results[-(N-1):]

    print("\n".join(results))

if __name__ == "__main__":
    solve()
